    17	    /**
    18	     * Each risk the office recognises is assessed on its own; an item that carries
    19	     * several risks carries the sum of their rates.
    20	     */
    21	    private double totalRateFor(Item item) {
    22	        double rate = 0;
    23	        for (RecognisedRisk risk : RecognisedRisk.values()) {
    24	            if (risk.isCarriedBy(item)) {
