    13	    private final AlikeItems alikeItems = new AlikeItems();
    14	    private final ComponentBlockOffer blockOffer = new ComponentBlockOffer();
    15	
    16	    public double forItems(List<Item> items) {
    17	        double total = 0;
    18	        for (List<Item> group : alikeItems.groupsIn(items)) {
    19	            total += blockOffer.basePremiumFor(group);
    20	        }
    21	        return total;
    22	    }
