    16	    private double totalRateFor(QuoteAssessment assessment) {
    17	        double rate = 0;
    18	        for (PolicyWideModifier modifier : PolicyWideModifier.values()) {
    19	            if (modifier.isCarriedBy(assessment)) {
    20	                rate += modifier.rate();
    21	            }
    22	        }
    23	        return rate;
    24	    }
