     1	/**
     2	 * A modifier the MHPCO assesses against the policy base premium as a whole, and the
     3	 * signed rate it carries.
     4	 *
     5	 * The office's catalogue of policy-wide modifiers: each entry names one, says when a
     6	 * quote carries it, and at what rate. A surcharge carries a positive rate, a discount a
     7	 * negative one. Revising a rate or an eligibility rule is a change to one entry;
     8	 * recognising a new modifier is a new entry.
     9	 *
    10	 * Eligibility is asked of the quote being assessed, not of the customer: an entry reads
    11	 * whatever of the quote it needs -- who the customer is, which contract this is -- and
    12	 * an entry that needs none of it, such as the initial assessment, simply says so.
    13	 *
    14	 * Unlike a recognised risk, which attaches to the one item that carries it, these are
    15	 * assessed against the sum of all item base premiums.
    16	 */
    17	public enum PolicyWideModifier {
    18	
    19	    /**
    20	     * Every quote is a first insurance of its items, so the office charges the initial
    21	     * assessment on every quote, whatever the customer's history.
    22	     */
    23	    INITIAL_ASSESSMENT(0.10) {
    24	        @Override
    25	        boolean isCarriedBy(QuoteAssessment assessment) {
    26	            return true;
    27	        }
    28	    },
    29	
    30	    LOYALTY_DISCOUNT(-0.20) {
    31	        @Override
    32	        boolean isCarriedBy(QuoteAssessment assessment) {
    33	            return assessment.customer().isLongStanding();
    34	        }
    35	    },
    36	
    37	    /**
    38	     * The office grants a discount on each contract the customer takes out after the
    39	     * first one.
    40	     */
    41	    FOLLOW_UP_CONTRACT_DISCOUNT(-0.15) {
    42	        @Override
    43	        boolean isCarriedBy(QuoteAssessment assessment) {
    44	            return assessment.isFollowUpContract();
    45	        }
    46	    };
    47	
    48	    private final double rate;
    49	
    50	    PolicyWideModifier(double rate) {
    51	        this.rate = rate;
    52	    }
    53	
    54	    abstract boolean isCarriedBy(QuoteAssessment assessment);
    55	
    56	    double rate() {
    57	        return rate;
    58	    }
    59	}
